const PALETTE = ['#2a78d6', '#1baf7a', '#eda100', '#008300', '#4a3aa7', '#e34948', '#e87ba4', '#eb6834']
// Colour e-paper (a Spectra's six inks): series in the inks themselves, which
// read on white; a mixed colour turns into confetti there.
const INKS = ['#0000ff', '#ff0000', '#00a000', '#000000', '#ffaa00']
// No colour (black and white, or greys): every series black, told apart by its
// dashes and its marks, never by a grey.
const DASHES = ['', '7 4', '2 4', '10 4 2 4']

// How the chart is drawn: 'color' as configured; 'contrast' black on white
// where the panel shows no colour (or the scene's Contrast setting asks for
// it); 'ink' on white in solid inks on colour e-paper.
function lookFor(app) {
  const mode = (app.state && app.state.contrast) || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return 'contrast'
  if (mode === 'auto' && app.frame.paper === true) return 'ink'
  return 'color'
}

const esc = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

const num = (v) => {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  if (typeof v === 'string' && v.trim() !== '') return Number(v.trim())
  return NaN
}

const fmt = (v) => (Math.abs(v - Math.round(v)) < 1e-9 ? String(Math.round(v)) : String(Number(v.toFixed(2))))

const r1 = (v) => Math.round(v * 10) / 10

function parse(data) {
  if (typeof data === 'string') {
    if (!data.trim()) return { series: [], labels: [] }
    try {
      data = JSON.parse(data)
    } catch (e) {
      return { series: [], labels: [] }
    }
  }
  if (Array.isArray(data)) {
    const labels = data.map((item) => (item && typeof item === 'object' ? String(item.label ?? item.name ?? '') : ''))
    const values = data.map((item) =>
      item && typeof item === 'object' ? num('value' in item ? item.value : item.y) : num(item)
    )
    return { series: [{ values }], labels: labels.some(Boolean) ? labels : [] }
  }
  if (!data || typeof data !== 'object') return { series: [], labels: [] }
  const entry = (s) =>
    Array.isArray(s)
      ? { values: s.map(num) }
      : s && typeof s === 'object'
      ? { name: s.name ?? s.label, color: s.color, values: (s.values ?? s.data ?? []).map(num) }
      : { values: [num(s)] }
  const series = Array.isArray(data.series) ? data.series.map(entry) : 'values' in data ? [entry(data)] : []
  const labels = Array.isArray(data.labels) ? data.labels.map((l) => (typeof l === 'number' ? fmt(l) : String(l ?? ''))) : []
  return { series: series.filter((s) => s.values.length), labels }
}

function yRange(series, minY, maxY, includeZero) {
  let lo = Infinity
  let hi = -Infinity
  for (const s of series) {
    for (const v of s.values) {
      if (Number.isFinite(v)) {
        lo = Math.min(lo, v)
        hi = Math.max(hi, v)
      }
    }
  }
  if (lo > hi) {
    lo = 0
    hi = 1
  }
  if (includeZero) {
    lo = Math.min(lo, 0)
    hi = Math.max(hi, 0)
  }
  const fixedLo = String(minY ?? '').trim() !== '' && Number.isFinite(Number(minY))
  const fixedHi = String(maxY ?? '').trim() !== '' && Number.isFinite(Number(maxY))
  if (fixedLo) lo = Number(minY)
  if (fixedHi) hi = Number(maxY)
  if (lo > hi) [lo, hi] = [hi, lo]
  if (hi - lo < 1e-9) {
    const pad = Math.max(Math.abs(lo) * 0.1, 1)
    lo -= pad
    hi += pad
  }
  // Grid steps of 1, 2, 2.5 or 5 x 10^n; an automatic end moves out to one.
  const rough = (hi - lo) / 4
  const magnitude = Math.pow(10, Math.floor(Math.log10(rough)))
  const step = [1, 2, 2.5, 5, 10].map((m) => m * magnitude).find((m) => m >= rough)
  if (!fixedLo) lo = Math.floor(lo / step + 1e-9) * step
  if (!fixedHi) hi = Math.ceil(hi / step - 1e-9) * step
  return [lo, hi, step]
}

export function get(app, context) {
  const c = app.config
  // The size the chart is drawn at: the box it feeds, else the canvas. Both
  // are in scene pixels, already turned with the frame.
  const W = Math.round(context.targetWidth || context.imageWidth || 0)
  const H = Math.round(context.targetHeight || context.imageHeight || 0)
  if (!(W > 0 && H > 0)) throw new Error('No canvas to draw on: this app runs on render.')
  const unit = Math.min(W, H)
  const look = lookFor(app)
  const plain = look !== 'color'
  // An empty number field comes in as 0: that is "scale with the chart" too.
  const size = (value, auto) => (Number(value) > 0 ? Number(value) : auto)
  const fontSize = size(c.fontSize, Math.max(11, Math.round(unit / 26)))
  const lineWidth = size(c.lineWidth, Math.max(plain ? 2.5 : 2, r1(unit / (plain ? 150 : 200))))
  const padding = size(c.padding, Math.max(6, Math.round(unit / 30)))
  const type = ['line', 'bar', 'area'].includes(c.chartType) ? c.chartType : 'line'
  const ink = plain ? '#000000' : c.axisColor || '#333333'
  const out = [`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">`]
  if (plain) {
    out.push(`<rect width="${W}" height="${H}" fill="#ffffff"/>`)
  } else if (String(c.transparentBackground) === 'false') {
    out.push(`<rect width="${W}" height="${H}" fill="${esc(c.backgroundColor || '#ffffff')}"/>`)
  }
  const text = (x, y, s, size, anchor, baseline = 'middle') =>
    out.push(
      `<text x="${r1(x)}" y="${r1(y)}" font-size="${r1(size)}" fill="${esc(ink)}" text-anchor="${anchor}" dominant-baseline="${baseline}">${esc(s)}</text>`
    )
  const done = () => frameos.svg(out.join('') + '</svg>', { width: W, height: H })
  // A series' colour, its dashes and its mark in this look.
  const colorOf = (s, si) => {
    if (look === 'contrast') return '#000000'
    if (look === 'ink') {
      if (s.color) return s.color
      if (si === 0 && c.color && String(c.color).toLowerCase() !== PALETTE[0]) return c.color
      return INKS[si % INKS.length]
    }
    return s.color || (si === 0 ? c.color || PALETTE[0] : PALETTE[si % PALETTE.length])
  }
  const dashOf = (si) => {
    const dash = look === 'contrast' ? DASHES[si % DASHES.length] : ''
    return dash ? ` stroke-dasharray="${dash.split(' ').map((n) => r1(Number(n) * Math.max(1, lineWidth / 2))).join(' ')}"` : ''
  }
  // Black and white: each point marked, filled, hollow, a square, a hollow square.
  const mark = (x, y, si, color) => {
    const r = r1(Math.max(lineWidth * 1.4, 3))
    const hollow = si % 2 === 1
    const fill = hollow ? '#ffffff' : color
    const stroke = `stroke="${color}" stroke-width="${r1(Math.max(1.5, lineWidth * 0.7))}"`
    if (Math.floor(si / 2) % 2 === 0) out.push(`<circle cx="${r1(x)}" cy="${r1(y)}" r="${r}" fill="${fill}" ${stroke}/>`)
    else out.push(`<rect x="${r1(x - r)}" y="${r1(y - r)}" width="${r1(r * 2)}" height="${r1(r * 2)}" fill="${fill}" ${stroke}/>`)
  }

  const { series, labels } = parse(c.data)
  if (!series.some((s) => s.values.some(Number.isFinite))) {
    text(W / 2, H / 2, 'No chart data', Math.max(8, Math.min(32, unit / 8)), 'middle')
    return done()
  }
  const [lo, hi, step] = yRange(series, c.minY, c.maxY, type !== 'line')
  const levels = []
  for (let v = hi; v >= lo - step * 1e-6 && levels.length < 12; v -= step) levels.push(v)
  const points = series.reduce((most, s) => Math.max(most, s.values.length), 0)
  const named = series.map((s, si) => ({ name: String(s.name ?? '').trim() || `Series ${si + 1}`, si }))
  const legend = series.length > 1 && series.some((s) => String(s.name ?? '').trim())
  const showLabels = String(c.showLabels) !== 'false'
  // On a round panel the plot is a wide box whose corners touch the circle
  // 12 px in from its rim, the title and the legend in the arc over it and
  // the day names in the arc under it.
  let left = 0
  let top = 0
  let right = W
  let bottom = H
  let legendRoom = W - padding * 2
  if (context.round === true) {
    const rim = unit / 2 - 12
    const halfH = rim * 0.55
    const halfW = Math.floor(Math.sqrt(rim * rim - halfH * halfH))
    left = W / 2 - halfW
    right = W / 2 + halfW
    top = H / 2 - halfH - padding - (c.title ? fontSize * 1.75 : 0) - (legend ? fontSize * 1.6 : 0)
    bottom = H / 2 + halfH + padding + (showLabels && labels.length ? fontSize * 2.05 : 0)
    const legendY = halfH + fontSize * 0.85
    legendRoom = 2 * Math.floor(Math.sqrt(Math.max(0, rim * rim - legendY * legendY))) - padding * 2
  }
  let plotX = left + padding
  let plotY = top + padding
  let plotRight = right - padding
  let plotBottom = bottom - padding
  if (c.title) {
    text(W / 2, plotY + fontSize * 0.875, c.title, fontSize * 1.25, 'middle')
    plotY += fontSize * 1.75
  }
  // A legend under the title when there is more than one series to tell apart:
  // each one's line (its dashes and its mark in black and white) and its name.
  if (legend) {
    const room = Math.min(right - left - padding * 2, legendRoom)
    const swatch = (f) => f * 1.8
    const widthAt = (f) => named.reduce((sum, n) => sum + swatch(f) + f * 0.4 + n.name.length * f * 0.56 + f * 1.2, -f * 1.2)
    let f = fontSize
    while (f > 9 && widthAt(f) > room) f -= 0.5
    let x = W / 2 - Math.min(widthAt(f), room) / 2
    const y = plotY + f * 0.75
    named.forEach(({ name, si }) => {
      const color = esc(colorOf(series[si], si))
      if (type === 'bar') {
        out.push(`<rect x="${r1(x)}" y="${r1(y - f * 0.4)}" width="${r1(swatch(f))}" height="${r1(f * 0.8)}" fill="${look === 'contrast' && si % 2 ? '#ffffff' : color}" stroke="${color}" stroke-width="${look === 'contrast' ? 1.5 : 0}"/>`)
      } else {
        out.push(`<path d="M${r1(x)} ${r1(y)}h${r1(swatch(f))}" stroke="${color}" stroke-width="${r1(lineWidth)}"${dashOf(si)} stroke-linecap="round" fill="none"/>`)
        if (look === 'contrast') mark(x + swatch(f) / 2, y, si, color)
      }
      x += swatch(f) + f * 0.4
      out.push(
        `<text x="${r1(x)}" y="${r1(y)}" font-size="${r1(f)}" fill="${esc(ink)}" text-anchor="start" dominant-baseline="middle">${esc(name)}</text>`
      )
      x += name.length * f * 0.56 + f * 1.2
    })
    plotY += f * 1.6
  }
  // The values' labels a little in from the edge, the day names a little
  // lower than the lowest value's label reaches, so the two never meet at
  // the corner.
  const gutter = showLabels ? levels.reduce((most, v) => Math.max(most, fmt(v).length), 0) * fontSize * 0.6 + fontSize * 0.7 : 0
  plotX += gutter
  if (showLabels && labels.length) plotBottom -= fontSize * 2.05
  // A line's last point is on the right edge: room for half its label there.
  if (showLabels && labels.length && type !== 'bar') plotRight -= (String(labels[points - 1] || '').length * fontSize * 0.56) / 2
  const plotW = plotRight - plotX
  const plotH = plotBottom - plotY
  if (plotW < 8 || plotH < 8) {
    text(W / 2, H / 2, 'Not enough space', Math.max(8, Math.min(32, unit / 8)), 'middle')
    return done()
  }
  const yOf = (v) => plotY + plotH - ((v - lo) / (hi - lo)) * plotH
  const xOf = (i) =>
    type === 'bar' ? plotX + ((i + 0.5) * plotW) / points : points === 1 ? plotX + plotW / 2 : plotX + (plotW * i) / (points - 1)
  const baseY = yOf(Math.min(Math.max(0, lo), hi))

  if (String(c.showGrid) !== 'false') {
    const d = levels.map((v) => `M${r1(plotX)} ${r1(yOf(v))}h${r1(plotW)}`).join('')
    // Without greys a grid line is dotted ink, not a faint one.
    if (plain) out.push(`<path d="${d}" stroke="${esc(ink)}" stroke-dasharray="1 4" stroke-width="1" fill="none"/>`)
    else out.push(`<path d="${d}" stroke="${esc(ink)}" stroke-opacity="0.25" stroke-width="1" fill="none"/>`)
  }

  series.forEach((s, si) => {
    const color = esc(colorOf(s, si))
    if (type === 'bar') {
      const d = []
      if (points > plotW) {
        const cols = Math.max(Math.floor(plotW), 1)
        const top = new Array(cols).fill(Infinity)
        const bottom = new Array(cols).fill(-Infinity)
        s.values.forEach((v, i) => {
          if (!Number.isFinite(v)) return
          const col = Math.min(cols - 1, Math.floor((i * cols) / points))
          top[col] = Math.min(top[col], yOf(v), baseY)
          bottom[col] = Math.max(bottom[col], yOf(v), baseY)
        })
        for (let i = 0; i < cols; i++) {
          if (top[i] <= bottom[i]) d.push(`M${r1(plotX + i)} ${r1(top[i])}h1v${r1(Math.max(bottom[i] - top[i], 1))}h-1z`)
        }
      } else {
        const groupW = plotW / points
        const innerW = groupW * 0.8
        const gap = Math.min(2, innerW / (series.length * 4))
        const barW = Math.max(1, (innerW - gap * (series.length - 1)) / series.length)
        s.values.forEach((v, i) => {
          if (!Number.isFinite(v)) return
          const x = plotX + i * groupW + (groupW - innerW) / 2 + si * (barW + gap)
          const y = yOf(v)
          d.push(`M${r1(x)} ${r1(Math.min(y, baseY))}h${r1(barW)}v${r1(Math.max(Math.abs(baseY - y), 1))}h${r1(-barW)}z`)
        })
      }
      if (look === 'contrast' && si % 2 === 1) out.push(`<path d="${d.join('')}" fill="#ffffff" stroke="${color}" stroke-width="1.5"/>`)
      else out.push(`<path d="${d.join('')}" fill="${color}"/>`)
      return
    }
    for (let i = 0; i < s.values.length; ) {
      if (!Number.isFinite(s.values[i])) {
        i++
        continue
      }
      let end = i
      while (end + 1 < s.values.length && Number.isFinite(s.values[end + 1])) end++
      if (end === i) {
        out.push(`<circle cx="${r1(xOf(i))}" cy="${r1(yOf(s.values[i]))}" r="${r1(Math.max(lineWidth, 2))}" fill="${color}"/>`)
      } else {
        const pts = []
        for (let j = i; j <= end; j++) pts.push(`${r1(xOf(j))} ${r1(yOf(s.values[j]))}`)
        // A see-through fill is a grey or a mixed colour on e-paper: there the line alone.
        if (type === 'area' && !plain) {
          const area = `M${r1(xOf(i))} ${r1(baseY)}L${pts.join('L')}L${r1(xOf(end))} ${r1(baseY)}Z`
          out.push(`<path d="${area}" fill="${color}" fill-opacity="0.35"/>`)
        }
        const stroke = `stroke="${color}" stroke-width="${r1(lineWidth)}"${dashOf(si)} stroke-linecap="round" stroke-linejoin="round"`
        out.push(`<path d="M${pts.join('L')}" ${stroke} fill="none"/>`)
        if (look === 'contrast' && end - i < plotW / (lineWidth * 6)) {
          for (let j = i; j <= end; j++) mark(xOf(j), yOf(s.values[j]), si, color)
        }
      }
      i = end + 1
    }
  })

  out.push(`<path d="M${r1(plotX)} ${r1(plotY)}v${r1(plotH)}h${r1(plotW)}" stroke="${esc(ink)}" stroke-width="1" fill="none"/>`)
  if (showLabels) {
    levels.forEach((v) => text(plotX - fontSize * 0.3, yOf(v), fmt(v), fontSize, 'end'))
    if (labels.length) {
      const widest = labels.reduce((most, l) => Math.max(most, l.length), 0) * fontSize * 0.56 + fontSize * 0.5
      const step = Math.max(1, Math.ceil(((type === 'bar' ? points : points - 1) * widest) / plotW))
      for (let i = 0; i < points; i += step) {
        // Under its tick, moved in only as far as keeps it inside the padding.
        const half = (String(labels[i] || '').length * fontSize * 0.56) / 2
        const x = Math.min(Math.max(xOf(i), left + padding + half), right - padding - half)
        if (labels[i]) text(x, plotBottom + fontSize * 0.9, labels[i], fontSize, 'middle', 'hanging')
      }
    }
  }
  return done()
}
